const sample={schema:1,id:'gallim-forest-v1',title:'여우비와 커튼월',description:'잊혀진 숲에서 시작되는, 오직 당신만의 이야기.',start:'arrival',scenes:[{id:'arrival',title:'낯선 숲의 입구',body:'눈을 뜨자, 이름 모를 숲이 당신을 감싸고 있습니다.\n젖은 흙의 향기와 멀리서 들려오는 작은 종소리.\n\n발치에는 두 갈래 길이 놓여 있습니다.\n한쪽은 희미한 빛이, 다른 쪽은 깊은 안개가 이끕니다.\n\n당신은 어디로 향하겠습니까?',image:forest,choices:[{id:'follow-light',label:'희미한 빛을 따라간다',description:'나뭇잎 사이로 따스한 빛이 스며듭니다.',target:'clearing',effect:'glow',delta:1,min:0},{id:'enter-mist',label:'안개 속으로 걸어간다',description:'알 수 없는 속삭임이 당신을 부릅니다.',target:'mist',effect:'fade',delta:2,min:0}]},{id:'clearing',title:'빛이 머무는 자리',body:'숲이 열리고, 작은 공터가 나타납니다.\n오래된 우물 위에 은빛 열쇠가 놓여 있습니다.\n\n열쇠를 쥐자 마음속에 잊고 있던 용기가 차오릅니다.',image:forest,choices:[{id:'take-key',label:'열쇠를 들고 문을 찾는다',description:'당신의 다음 이야기가 기다립니다.',target:'ending',effect:'glow',delta:2,min:0}]},{id:'mist',title:'안개 너머의 목소리',body:'안개 속에서 작은 그림자가 다가옵니다.\n“길을 잃었니? 아니면, 길을 찾으러 왔니?”\n\n그 목소리를 따라 한 걸음 더 내딛습니다.',image:forest,choices:[{id:'trust-voice',label:'목소리를 믿고 따라간다',description:'두려움 너머로 한 걸음.',target:'ending',effect:'shake',delta:1,min:0}]},{id:'ending',title:'새로운 시작',body:'마침내 숲의 끝에 도착했습니다.\n뒤돌아보니 당신이 걸어온 길에 작은 꽃들이 피어 있습니다.\n\n어떤 선택도 헛되지 않았습니다.\n이제, 당신만의 이야기를 써 내려갈 차례입니다.',image:forest,choices:[]}]};
function testThemesEnabled(){
 return document.documentElement?.getAttribute?.('data-release-channel')==='test';
}
const storagePrefix=testThemesEnabled()?'sunshower.test.':'';
const projectStorageKey=storagePrefix+'gallim.project';
