const standalone=!!window.GALLIM_PROJECT;let storageOK=true,project;
try{project=validate(standalone?window.GALLIM_PROJECT:JSON.parse(localStorage.getItem(projectStorageKey)))}catch{project=clone(sample)}
project.title='여우비와 커튼월';
if(project.id===sample.id)project.scenes.forEach(scene=>{scene.image='';});
let nameCompositionActive=false;
let renderedBuildingScene=null;
let customSection=null;
